-- قاموس السجلات الموحد وربطه بمحرك التكليفات
begin;
on conflict(module_key) do update set display_name=excluded.display_name,owner_role=excluded.owner_role,route_url=excluded.route_url,is_active=true;

on conflict(module_key,record_type) do update set display_name=excluded.display_name,route_url=excluded.route_url,is_assignable=true,supports_files=excluded.supports_files,supports_approval=excluded.supports_approval,supports_analysis=true,configuration_json=excluded.configuration_json,is_active=true;
commit;
